def transform(grid):
    if not grid or not grid[0]:
        return grid

    height = len(grid)
    width = len(grid[0])

    # Find smallest repeating horizontal pattern
    for p in range(1, width // 2 + 1):
        if width % p == 0:
            valid = True
            for r in range(height):
                for c in range(width):
                    if grid[r][c] != grid[r][c % p]:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                return [row[:p] for row in grid]

    return grid
